-export function totalCents(lines, discountPercent) { return lines.reduce((sum, line) => sum + Math.round(line.cents * line.quantity * (1 - discountPercent / 100)), 0); }
+// Order matters: sum the integer line cents first, apply the percentage
+// discount to the subtotal, then round exactly once. Rounding per line makes
+// multi-line receipts drift upward (two 1-cent lines at 50% bill 2, not 1).
+export function totalCents(lines, discountPercent) {
+  const subtotalCents = lines.reduce((sum, line) => sum + line.cents * line.quantity, 0);
+  return Math.round(subtotalCents * (1 - discountPercent / 100));
+}

