 export const defaultPageSize = 20;
+
+/**
+ * Slice `items` into a single one-based page.
+ *
+ * @param {ArrayLike<unknown>} items Source collection. It is never mutated.
+ * @param {number} page One-based page number; must be a positive integer.
+ * @param {number} pageSize Items per page; must be a positive integer.
+ * @returns {{ items: unknown[], total: number, pageCount: number }} A fresh,
+ *   copied slice of `items` plus the collection size and the total page count.
+ * @throws {RangeError} If `page` or `pageSize` is not a positive integer.
+ */
+export function paginate(items, page, pageSize) {
+  if (!Number.isInteger(page) || page < 1) {
+    throw new RangeError(
+      `paginate: page must be a positive integer, received ${String(page)}`,
+    );
+  }
+  if (!Number.isInteger(pageSize) || pageSize < 1) {
+    throw new RangeError(
+      `paginate: pageSize must be a positive integer, received ${String(pageSize)}`,
+    );
+  }
+
+  const total = items.length;
+  const pageCount = Math.ceil(total / pageSize);
+  const start = (page - 1) * pageSize;
+
+  // slice() copies, so callers cannot mutate the source through the result.
+  return { items: items.slice(start, start + pageSize), total, pageCount };
+}

